function z80_generate_mn_r() {
    let ostr = 'const Z80_MN_R = Object.freeze({\n';
    for (let k in Z80_MN) {
        ostr += '  ' + Z80_MN[k] + ': \'' + k + '\',\n'
    }
    return ostr + '});';
}
