function Z80_fill_mnemonics(what) {
    for (let i in what) {
        let o = what[i];
        if (o.mnemonic === '') {
            let ostr = Z80_MN_R[o.ins];
            if (o.arg1 !== null) ostr += ' ' + o.arg1;
            if (o.arg2 !== null) ostr += ' ' + o.arg2;
            if (o.arg3 !== null) ostr += ' ' + o.arg3;
            o.mnemonic = ostr;
        }
    }
    return what;
}

